'use strict';
const canvas=document.querySelector('#game'),M=Meadow,flock=new Map(),keys={},pending={},flowers=[];let last=0,time=0,ui='',diag=0,keyboardEnabled=false,lastKey='none',lastKeyAt=0,hatNoticeUntil=0;const hatNames=['No hat','Sunhat','Party hat','Flower crown'];const empty={x:0,y:0,jump:false,baa:false,bite:false,hat:false};
const audio=MeadowAudio.create();
let view;
try{view=Meadow3D.create(canvas);}catch(error){view=MeadowFallback.create(canvas);document.querySelector('#toast').textContent='Reduced graphics mode · WebGL unavailable';}
function background(){view.begin();}function drawSheep(s,ghost=false){view.sheep(s,ghost);}
function join(id){if(flock.has(id))return flock.get(id);if(flock.size>=4)return null;const n=[0,1,2,3].find(n=>![...flock.values()].some(s=>s.n===n));const s=M.sheep(id,n);flock.set(id,s);document.querySelector('#welcome').hidden=true;return s;}
function baa(s){audio.play('baa');}
function scan(){try{return navigator.getGamepads?Array.from(navigator.getGamepads()).filter(p=>p&&p.connected):[];}catch(e){return[];}}
function keyboardInput(){let x=(keys.ArrowRight||keys.KeyD?1:0)-(keys.ArrowLeft||keys.KeyA?1:0),y=(keys.ArrowDown||keys.KeyS?1:0)-(keys.ArrowUp||keys.KeyW?1:0);let l=Math.hypot(x,y);return{x:l>1?x/l:x,y:l>1?y/l:y,jump:!!(keys.Space||pending.Space),baa:!!(keys.KeyX||pending.KeyX),bite:!!(keys.KeyB||pending.KeyB),hat:!!(keys.KeyH||pending.KeyH)};}
function frame(t){const dt=Math.min((t-last)/1000||0,.05);last=t;time+=dt;const pads=scan();for(const p of pads){if(p.buttons[0]?.pressed)join('pad'+p.index);}for(const s of flock.values()){const p=pads.find(p=>'pad'+p.index===s.id);s.connected=s.id==='keys'||!!p;let i=s.id==='keys'?keyboardInput():p?M.input(p):empty;if(s.id==='keys'){for(const [code,action]of [['Space','jump'],['KeyX','baa'],['KeyB','bite'],['KeyH','hat']])if(pending[code])s.prev[action]=false;}const old=s.baa,oldHat=s.hat;M.step(s,i,document.hidden?0:dt);if(s.id==='keys')for(const code in pending)delete pending[code];if(s.baa>old)baa(s);if(s.attack)audio.play('chomp');if(s.hat!==oldHat){document.querySelector('#hatNotice').textContent='P'+(s.n+1)+': '+hatNames[s.hat];hatNoticeUntil=time+3;}}
M.combat([...flock.values()]);background();if(!flock.size){[[250,300],[430,500],[650,220],[850,410],[720,570],[360,220],[550,380],[920,590]].forEach(([x,y],n)=>{const s=M.sheep('demo',n);s.x=x;s.y=y;s.walk=time*.8;s.face=n%2?1:-1;s.heading=n%2?.4:-2.3;s.hat=n===3?1:0;drawSheep(s,true);});}else [...flock.values()].sort((a,b)=>a.y-b.y).forEach(s=>drawSheep(s));
view.render(time);document.querySelector('#hatNotice').hidden=time>hatNoticeUntil;const status=[...flock.values()].map(s=>`<span class="chip"><i style="background:${s.color}"></i>${s.id==='keys'?'Shared keyboard / touch':'P'+(s.n+1)+' · gamepad slot '+s.id.slice(3)}${s.connected?' · '+hatNames[s.hat]:' · reconnect controller'}</span>`).join('');if(status!==ui){document.querySelector('#players').innerHTML=status;ui=status;}
if(t-diag>200){diag=t;const audioState=audio.status().label;const slotText=pads.map(p=>'slot '+p.index+' ['+(flock.has('pad'+p.index)?'joined':'press A')+']').join(' · ');document.querySelector('#inputHud').textContent='v8 · Gamepads: '+pads.length+' · '+(slotText||'No separate controller slots yet')+' | Keys: '+(keyboardEnabled?'shared fallback ON':'fallback OFF')+' ('+lastKey+')'+' | Audio: '+audioState;document.querySelector('#padStatus').textContent=(navigator.getGamepads?'Gamepad API available':'Gamepad API unavailable')+'\nSeparate controller slots: '+pads.length+' / Sheep joined: '+flock.size+'\nLast keyboard event: '+lastKey+(lastKeyAt?' ('+Math.round((performance.now()-lastKeyAt)/1000)+'s ago)':'')+'\nKeyboard events have no controller identity. Fallback is '+(keyboardEnabled?'ON (one shared sheep)':'OFF')+'.\nAudio engine: '+audioState+'\n'+pads.map(p=>'SLOT '+p.index+': '+p.id+'\n mapping: '+(p.mapping||'nonstandard')+' | axes: '+p.axes.map(x=>x.toFixed(2)).join(', ')+' | held buttons: '+(p.buttons.map((b,i)=>b.pressed?i:null).filter(x=>x!==null).join(', ')||'none')).join('\n');updateSoundLabel();}requestAnimationFrame(frame);}
function updateSoundLabel(){document.querySelector('#inputMode').textContent=keyboardEnabled?'Keyboard: WASD / arrows · Space hop · X baa · B chomp · H hat':'Controller: stick / D-pad · A hop · X baa · B chomp · Y hat';const state=audio.status();document.querySelector('#sound').textContent=state.effectsEnabled?'Sounds on':'Sounds off';document.querySelector('#sound').setAttribute('aria-pressed',String(state.effectsEnabled));document.querySelector('#music').textContent=state.musicEnabled?'Music on':'Music off';document.querySelector('#music').setAttribute('aria-pressed',String(state.musicEnabled));document.querySelector('#audioStart').hidden=state.state==='running';document.querySelector('#audioStatus').textContent='Audio: '+state.label+' · Music '+(state.musicPlaying?'playing':state.musicEnabled?'enabled':'off')+' · Sound effects '+(state.effectsEnabled?'enabled':'off');}
function enableSound(test=false){audio.activate().then(()=>audio.preload()).then(()=>{if(test)audio.play('baa');updateSoundLabel();});}
document.querySelector('#start').onclick=()=>{enableSound();document.querySelector('#welcome').hidden=true;canvas.focus();};
document.querySelector('#keyboard').onclick=()=>{keyboardEnabled=!keyboardEnabled;clear();if(keyboardEnabled){const s=join('keys');if(!s){keyboardEnabled=false;document.querySelector('#toast').textContent='All four sheep slots are occupied.';}else enableSound();}else flock.delete('keys');document.querySelector('#keyboard').textContent=keyboardEnabled?'Turn off shared keys':'Keyboard / touch';canvas.focus();};document.querySelector('#sound').onclick=()=>{audio.setEffects(!audio.status().effectsEnabled);enableSound(false);updateSoundLabel();};document.querySelector('#music').onclick=()=>{audio.setMusic(!audio.status().musicEnabled);enableSound(false);updateSoundLabel();};document.querySelector('#audioStart').onclick=()=>enableSound(true);document.querySelector('#testBaa').onclick=()=>enableSound(true);document.querySelector('#testChomp').onclick=()=>{audio.activate().then(()=>audio.preload()).then(()=>audio.play('chomp'));};
document.querySelector('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(e){document.querySelector('#toast').textContent='Use your browser’s full-screen option.';}};document.querySelector('#help').onclick=()=>{const d=document.querySelector('#diagnostics');d.open=!d.open;};
const allowed=['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD','Space','KeyX','KeyB','KeyH'];addEventListener('keydown',e=>{if(!allowed.includes(e.code)||/INPUT|TEXTAREA/.test(e.target.tagName))return;if(e.target.tagName==='BUTTON'&&(e.code==='Space'))return;lastKey=e.code;lastKeyAt=performance.now();if(!keyboardEnabled)return;e.preventDefault();keys[e.code]=true;if(!e.repeat&&['Space','KeyX','KeyB','KeyH'].includes(e.code))pending[e.code]=true;if(audio.status().state!=='running')enableSound(false);});addEventListener('keyup',e=>{keys[e.code]=false;});function clear(){for(const k in keys)keys[k]=false;for(const k in pending)delete pending[k];}addEventListener('blur',clear);document.addEventListener('visibilitychange',()=>{clear();audio.visibility(document.hidden);});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();keyboardEnabled=true;join('keys');enableSound(false);keys[b.dataset.key]=true;if(['Space','KeyX','KeyB','KeyH'].includes(b.dataset.key))pending[b.dataset.key]=true;b.setPointerCapture(e.pointerId);};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys[b.dataset.key]=false);});requestAnimationFrame(frame);
